      "rationale": "These spans supply the selection signal, proposed action, resource constraints, fallback and limits on interpreting persistence."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C022.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
